import { useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import db from './utils/firebase';

const RTC_CONFIGURATION = {
  iceServers: [{ urls: 'stun:stun.l.google.com:19302' }],
};

function VideoCall({ user, buttonTarget }) {
  const [call, setCall] = useState(null);
  const [incomingCall, setIncomingCall] = useState(null);
  const [callError, setCallError] = useState('');
  const [startingCall, setStartingCall] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const localVideoRef = useRef(null);
  const remoteVideoRef = useRef(null);
  const localPreviewRef = useRef(null);
  const dragStateRef = useRef(null);
  const peerRef = useRef(null);
  const localStreamRef = useRef(null);
  const callRef = useRef(null);
  const callDocumentUnsubscribeRef = useRef(null);
  const remoteCandidatesUnsubscribeRef = useRef(null);

  useEffect(() => {
    if (!user) return undefined;
    return db.collection('calls')
      .where('callee', '==', user)
      .onSnapshot(snapshot => {
        const invitation = snapshot.docs.find(doc =>
          doc.id !== (callRef.current && callRef.current.id) && doc.data().status === 'ringing'
        );
        setIncomingCall(invitation ? { id: invitation.id, ...invitation.data() } : null);
      }, () => setCallError('Unable to receive incoming calls.'));
  }, [user]);

  useEffect(() => {
    if (!call || !localVideoRef.current || !remoteVideoRef.current) return;
    if (localStreamRef.current) {
      localVideoRef.current.srcObject = localStreamRef.current;
      localVideoRef.current.play().catch(() => {});
    }
    if (peerRef.current && peerRef.current.remoteStream) {
      remoteVideoRef.current.srcObject = peerRef.current.remoteStream;
      remoteVideoRef.current.play().catch(() => {});
    }
  }, [call]);

  useEffect(() => {
    const handleFullscreenChange = () => {
      if (!document.fullscreenElement) setIsExpanded(false);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const releaseMedia = () => {
    if (callDocumentUnsubscribeRef.current) {
      callDocumentUnsubscribeRef.current();
      callDocumentUnsubscribeRef.current = null;
    }
    if (remoteCandidatesUnsubscribeRef.current) {
      remoteCandidatesUnsubscribeRef.current();
      remoteCandidatesUnsubscribeRef.current = null;
    }
    if (peerRef.current) {
      peerRef.current.ontrack = null;
      peerRef.current.onicecandidate = null;
      peerRef.current.close();
      peerRef.current = null;
    }
    if (localStreamRef.current) {
      localStreamRef.current.getTracks().forEach(track => track.stop());
      localStreamRef.current = null;
    }
    if (localVideoRef.current) localVideoRef.current.srcObject = null;
    if (remoteVideoRef.current) remoteVideoRef.current.srcObject = null;
  };

  const preparePeer = async () => {
    const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
    localStreamRef.current = stream;
    const peer = new RTCPeerConnection(RTC_CONFIGURATION);
    peerRef.current = peer;
    peer.remoteStream = new MediaStream();
    stream.getVideoTracks().forEach(track => peer.addTrack(track, stream));
    peer.ontrack = event => {
      event.streams[0].getTracks().forEach(track => peer.remoteStream.addTrack(track));
      if (remoteVideoRef.current) {
        remoteVideoRef.current.srcObject = peer.remoteStream;
        remoteVideoRef.current.play().catch(() => {});
      }
    };
    return { peer, stream };
  };

  const watchRemoteCandidates = (candidateCollection, peer) => {
    remoteCandidatesUnsubscribeRef.current = candidateCollection.onSnapshot(snapshot => {
      snapshot.docChanges().forEach(change => {
        if (change.type === 'added') {
          peer.addIceCandidate(new RTCIceCandidate(change.doc.data())).catch(() => {});
        }
      });
    });
  };

  const addLocalCandidates = (peer, candidateCollection) => {
    peer.onicecandidate = event => {
      if (event.candidate) candidateCollection.add(event.candidate.toJSON());
    };
  };

  const beginCall = async () => {
    if (startingCall || call) return;
    setCallError('');
    setStartingCall(true);
    try {
      const { peer } = await preparePeer();
      const callDocument = db.collection('calls').doc();
      const callee = user === 'Ananthu' ? 'Sneha' : 'Ananthu';
      const callData = {
        caller: user,
        callee,
        status: 'ringing',
        createdAt: Date.now(),
      };
      callRef.current = { id: callDocument.id, ...callData };
      setCall(callRef.current);
      addLocalCandidates(peer, callDocument.collection('callerCandidates'));
      const offer = await peer.createOffer();
      await peer.setLocalDescription(offer);
      await callDocument.set({ ...callData, offer: { type: offer.type, sdp: offer.sdp } });
      callDocumentUnsubscribeRef.current = callDocument.onSnapshot(async snapshot => {
        const data = snapshot.data();
        if (!data) return;
        if (data.answer && peer.signalingState === 'have-local-offer') {
          await peer.setRemoteDescription(new RTCSessionDescription(data.answer));
          watchRemoteCandidates(callDocument.collection('calleeCandidates'), peer);
          callRef.current = { ...callRef.current, status: 'connected' };
          setCall(current => current ? { ...current, status: 'connected' } : current);
        }
        if (data.status === 'ended') {
          releaseMedia();
          callRef.current = null;
          setCall(null);
        }
      });
    } catch (error) {
      releaseMedia();
      callRef.current = null;
      setCall(null);
      setCallError(error.name === 'NotAllowedError'
        ? 'Camera access was denied. Allow camera access to start a video call.'
        : 'Could not start the video call. Check camera availability and try again.');
    } finally {
      setStartingCall(false);
    }
  };

  const answerCall = async () => {
    if (!incomingCall) return;
    setCallError('');
    try {
      const { peer } = await preparePeer();
      const callDocument = db.collection('calls').doc(incomingCall.id);
      callRef.current = incomingCall;
      setCall(incomingCall);
      await peer.setRemoteDescription(new RTCSessionDescription(incomingCall.offer));
      addLocalCandidates(peer, callDocument.collection('calleeCandidates'));
      watchRemoteCandidates(callDocument.collection('callerCandidates'), peer);
      const answer = await peer.createAnswer();
      await peer.setLocalDescription(answer);
      await callDocument.update({
        answer: { type: answer.type, sdp: answer.sdp },
        status: 'connected',
      });
      callDocumentUnsubscribeRef.current = callDocument.onSnapshot(snapshot => {
        if (snapshot.data() && snapshot.data().status === 'ended') {
          releaseMedia();
          callRef.current = null;
          setCall(null);
        }
      });
      setIncomingCall(null);
    } catch (error) {
      releaseMedia();
      callRef.current = null;
      setCall(null);
      setCallError(error.name === 'NotAllowedError'
        ? 'Camera access was denied. Allow camera access to answer.'
        : 'Could not answer the video call. Check camera availability and try again.');
    }
  };

  const dismissCall = async () => {
    if (!incomingCall) return;
    await db.collection('calls').doc(incomingCall.id).update({ status: 'ended' });
    setIncomingCall(null);
  };

  const endCall = async () => {
    const activeCall = callRef.current;
    releaseMedia();
    callRef.current = null;
    setCall(null);
    if (activeCall) {
      await db.collection('calls').doc(activeCall.id).update({ status: 'ended' }).catch(() => {});
    }
  };

  const toggleExpanded = async () => {
    if (isExpanded) {
      if (document.fullscreenElement && document.exitFullscreen) {
        await document.exitFullscreen().catch(() => {});
      }
      setIsExpanded(false);
      return;
    }
    setIsExpanded(true);
    const panel = document.querySelector('.video-call-panel');
    if (panel && panel.requestFullscreen) {
      await panel.requestFullscreen().catch(() => {});
    }
  };

  const handlePreviewPointerDown = event => {
    if (!isExpanded || !localPreviewRef.current) return;
    const preview = localPreviewRef.current;
    const panel = preview.closest('.video-call-panel');
    const panelBounds = panel.getBoundingClientRect();
    const previewBounds = preview.getBoundingClientRect();
    dragStateRef.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      left: previewBounds.left - panelBounds.left,
      top: previewBounds.top - panelBounds.top,
      panelWidth: panelBounds.width,
      panelHeight: panelBounds.height,
      width: previewBounds.width,
      height: previewBounds.height,
    };
    preview.style.left = `${previewBounds.left - panelBounds.left}px`;
    preview.style.top = `${previewBounds.top - panelBounds.top}px`;
    preview.style.right = 'auto';
    preview.style.bottom = 'auto';
    preview.setPointerCapture(event.pointerId);
    event.preventDefault();
  };

  const handlePreviewPointerMove = event => {
    const drag = dragStateRef.current;
    if (!drag || drag.pointerId !== event.pointerId || !localPreviewRef.current) return;
    const preview = localPreviewRef.current;
    const inset = 8;
    const left = Math.max(inset, Math.min(
      drag.panelWidth - drag.width - inset,
      drag.left + event.clientX - drag.startX
    ));
    const top = Math.max(inset, Math.min(
      drag.panelHeight - drag.height - inset,
      drag.top + event.clientY - drag.startY
    ));
    preview.style.left = `${left}px`;
    preview.style.top = `${top}px`;
  };

  const handlePreviewPointerUp = event => {
    if (dragStateRef.current && dragStateRef.current.pointerId === event.pointerId) {
      dragStateRef.current = null;
    }
  };

  useEffect(() => () => releaseMedia(), []);

  return (
    <>
      {buttonTarget && createPortal(
        <button
          className="chat-attach video-call-button"
          onClick={beginCall}
          disabled={Boolean(call) || startingCall}
          title={startingCall ? 'Starting video call' : 'Start video call'}
          aria-label={startingCall ? 'Starting video call' : 'Start video call'}
        >
          <i className="fa fa-video-camera fa-lg" aria-hidden="true"></i>
        </button>,
        buttonTarget
      )}

      {incomingCall && !call && (
        <div className="incoming-call" role="status">
          <span>{incomingCall.caller} is calling</span>
          <button onClick={answerCall}>Answer</button>
          <button className="decline-call-button" onClick={dismissCall}>Decline</button>
        </div>
      )}

      {call && (
        <section className={`video-call-panel${isExpanded ? ' is-expanded' : ''}`} aria-label="Video call">
          <div className="video-call-heading">
            <span>{call.caller === user ? `Calling ${call.callee}` : `Video call with ${call.caller}`}</span>
            <button className="expand-call-button" onClick={toggleExpanded} aria-label={isExpanded ? 'Return to chat' : 'Expand video'} title={isExpanded ? 'Return to chat' : 'Expand video'}>
              <i className={`fa ${isExpanded ? 'fa-compress' : 'fa-expand'}`} aria-hidden="true"></i>
            </button>
            <button className="end-call-button" onClick={endCall} aria-label="End video call" title="End call">
              <i className="fa fa-phone" aria-hidden="true"></i>
            </button>
          </div>
          <div className="video-call-streams">
            <div
              ref={call.caller === user ? localPreviewRef : null}
              className={`video-stream caller-stream ${call.caller === user ? 'local-stream' : 'remote-stream'}`}
              onPointerDown={handlePreviewPointerDown}
              onPointerMove={handlePreviewPointerMove}
              onPointerUp={handlePreviewPointerUp}
              onPointerCancel={handlePreviewPointerUp}
            >
              <video className={call.caller === user ? 'local-video' : 'remote-video'} ref={call.caller === user ? localVideoRef : remoteVideoRef} autoPlay playsInline muted />
              <span>{call.caller} · caller</span>
            </div>
            <div
              ref={call.caller === user ? null : localPreviewRef}
              className={`video-stream callee-stream ${call.caller === user ? 'remote-stream' : 'local-stream'}`}
              onPointerDown={handlePreviewPointerDown}
              onPointerMove={handlePreviewPointerMove}
              onPointerUp={handlePreviewPointerUp}
              onPointerCancel={handlePreviewPointerUp}
            >
              <video className={call.caller === user ? 'remote-video' : 'local-video'} ref={call.caller === user ? remoteVideoRef : localVideoRef} autoPlay playsInline muted />
              <span>{call.callee} · callee</span>
            </div>
          </div>
          <div className="video-call-status">
            {call.status === 'ringing' ? 'Waiting for them to answer' : 'Video connected · audio off'}
          </div>
        </section>
      )}
      {callError && <div className="call-error" role="alert">{callError}</div>}
    </>
  );
}

export default VideoCall;